answer_code:
using System;

class Solution
{
    public static T? MaxOrNull<T>(T[] values) where T : struct, IComparable<T>
    {
        if (values == null || values.Length == 0)
        {
            return null;
        }
        T best = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i].CompareTo(best) > 0)
            {
                best = values[i];
            }
        }
        return best;
    }
}

