using System;

class Solution
{
    public interface IChecker<in T>
    {
        bool Check(T value);
    }

    public class NotNullChecker : IChecker<object>
    {
        public bool Check(object value)
        {
            return value != null;
        }
    }

    public static int CountMatching<T>(T[] items, IChecker<T> checker)
    {
        int count = 0;
        foreach (T item in items)
        {
            if (checker.Check(item))
            {
                count++;
            }
        }
        return count;
    }
}

