using System;
using System.Collections.Generic;

class Solution
{
    public class Ops<T>
    {
        public readonly T Zero;
        public readonly T One;
        public readonly Func<T, T, T> Add;
        public readonly Func<T, T, T> Multiply;

        public Ops(T zero, T one, Func<T, T, T> add, Func<T, T, T> multiply)
        {
            Zero = zero;
            One = one;
            Add = add;
            Multiply = multiply;
        }
    }

    public static T Sum<T>(IEnumerable<T> source, Ops<T> ops)
    {
        T acc = ops.Zero;
        foreach (T item in source)
        {
            acc = ops.Add(acc, item);
        }
        return acc;
    }

    public static T Product<T>(IEnumerable<T> source, Ops<T> ops)
    {
        T acc = ops.One;
        foreach (T item in source)
        {
            acc = ops.Multiply(acc, item);
        }
        return acc;
    }
}

