using System;
using System.Collections.Generic;
using System.Text;

class Solution
{
    public class Query
    {
        private readonly string _text;

        public Query(string text)
        {
            _text = text;
        }

        public string Text
        {
            get { return _text; }
        }
    }

    public class QueryBuilder
    {
        private readonly List<string> _conditions = new List<string>();
        private string _table;
        private string _orderBy;

        public QueryBuilder Table(string name)
        {
            _table = name;
            return this;
        }

        public QueryBuilder Where(string condition)
        {
            _conditions.Add(condition);
            return this;
        }

        public QueryBuilder OrderBy(string column)
        {
            _orderBy = column;
            return this;
        }

        public Query Build()
        {
            if (_table == null)
            {
                throw new InvalidOperationException("Table is required");
            }
            StringBuilder sb = new StringBuilder();
            sb.Append("SELECT * FROM ").Append(_table);
            if (_conditions.Count > 0)
            {
                sb.Append(" WHERE ").Append(string.Join(" AND ", _conditions));
            }
            if (_orderBy != null)
            {
                sb.Append(" ORDER BY ").Append(_orderBy);
            }
            return new Query(sb.ToString());
        }
    }
}

