using System;

class Solution
{
    public class Result<T>
    {
        private readonly T _value;
        private readonly string _error;
        private readonly bool _isOk;

        private Result(T value, string error, bool isOk)
        {
            _value = value;
            _error = error;
            _isOk = isOk;
        }

        public static Result<T> Ok(T value)
        {
            return new Result<T>(value, null, true);
        }

        public static Result<T> Fail(string error)
        {
            return new Result<T>(default(T), error, false);
        }

        public bool IsOk
        {
            get { return _isOk; }
        }

        public T Value
        {
            get
            {
                if (!_isOk)
                {
                    throw new InvalidOperationException("Result is a failure: " + _error);
                }
                return _value;
            }
        }

        public string Error
        {
            get { return _error; }
        }

        public R Match<R>(Func<T, R> onOk, Func<string, R> onError)
        {
            return _isOk ? onOk(_value) : onError(_error);
        }
    }

    public static Result<int> ParsePositive(string text)
    {
        int parsed;
        if (!int.TryParse(text, out parsed))
        {
            return Result<int>.Fail("not a number");
        }
        if (parsed < 1)
        {
            return Result<int>.Fail("not positive");
        }
        return Result<int>.Ok(parsed);
    }
}

