    public static Option<string> Lookup(IReadOnlyDictionary<string, string> dict, string key)
    {
        string found;
        if (key != null && dict.TryGetValue(key, out found))
        {
            return Option<string>.Some(found);
        }
        return Option<string>.None;
    }
