using System;

class Solution
{
    public abstract record Expr;

    public sealed record Num(int Value) : Expr;

    public sealed record Add(Expr Left, Expr Right) : Expr;

    public sealed record Mul(Expr Left, Expr Right) : Expr;

    public sealed record Neg(Expr Operand) : Expr;

    public static int Eval(Expr expr)
    {
        return expr switch
        {
            Num n => n.Value,
            Add a => Eval(a.Left) + Eval(a.Right),
            Mul m => Eval(m.Left) * Eval(m.Right),
            Neg g => -Eval(g.Operand),
            _ => throw new ArgumentException("unknown expression")
        };
    }

    public static string Print(Expr expr)
    {
        return expr switch
        {
            Num n => n.Value.ToString(),
            Add a => "(" + Print(a.Left) + "+" + Print(a.Right) + ")",
            Mul m => "(" + Print(m.Left) + "*" + Print(m.Right) + ")",
            Neg g => "-" + Print(g.Operand),
            _ => throw new ArgumentException("unknown expression")
        };
    }
}

