using System;
using System.Collections.Generic;

class Job
{
    public string Name { get; }
    public int Priority { get; }
    public Job(string name, int priority) { Name = name; Priority = priority; }
}

class Solution
{
    // 優先度の降順、同点なら名前の昇順 (序数比較) で並べる比較子
    public static IComparer<Job> ByPriorityThenName()
    {
        return Comparer<Job>.Create((a, b) =>
        {
            int byPriority = b.Priority.CompareTo(a.Priority);   // 降順なので b と a を入れ替える
            if (byPriority != 0) { return byPriority; }
            return string.CompareOrdinal(a.Name, b.Name);
        });
    }

    // cmp が sample の上で反対称性と推移律を満たすか総当たりで確かめる
    public static bool IsConsistent<T>(IComparer<T> cmp, IReadOnlyList<T> sample)
    {
        int n = sample.Count;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (Math.Sign(cmp.Compare(sample[i], sample[j])) != -Math.Sign(cmp.Compare(sample[j], sample[i])))
                {
                    return false;
                }
            }
        }
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                for (int k = 0; k < n; k++)
                {
                    bool ij = Math.Sign(cmp.Compare(sample[i], sample[j])) <= 0;
                    bool jk = Math.Sign(cmp.Compare(sample[j], sample[k])) <= 0;
                    bool ik = Math.Sign(cmp.Compare(sample[i], sample[k])) <= 0;
                    if (ij && jk && !ik) { return false; }
                }
            }
        }
        return true;
    }

    public static string[] SortedNames(Job[] jobs, IComparer<Job> cmp)
    {
        var copy = (Job[])jobs.Clone();
        Array.Sort(copy, cmp);
        var names = new string[copy.Length];
        for (int i = 0; i < copy.Length; i++) { names[i] = copy[i].Name; }
        return names;
    }
}

