using System.Collections.Generic;
using System.Threading.Tasks;

class AsyncWriter : IAsyncDisposable
{
    private readonly List<string> _log;
    private bool _disposed;

    public AsyncWriter(List<string> log) { _log = log; }

    public void Write(string s)
    {
        if (_disposed) throw new ObjectDisposedException(nameof(AsyncWriter));
        _log.Add("write:" + s);
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed) { return; }
        _disposed = true;
        await Task.Yield();
        _log.Add("flush");
        _log.Add("close");
    }
}

class Solution
{
    public static async Task<List<string>> UseAsync(string[] items)
    {
        var log = new List<string>();
        await using (var writer = new AsyncWriter(log))
        {
            foreach (var item in items)
            {
                writer.Write(item);
            }
        }
        return log;
    }
}

