using System;

class Solution
{
    // "HH:MM" を 0 時からの分数に変換する。
    // text が null なら ArgumentNullException (呼び出し側のバグ)。
    // 形式や範囲が不正なら FormatException (入力データの問題)。
    public static int ParseMinutes(string text)
    {
        if (text is null)
        {
            throw new ArgumentNullException(nameof(text));
        }
        int minutes;
        if (!TryParseMinutes(text, out minutes))
        {
            throw new FormatException("時刻として解釈できません: " + text);
        }
        return minutes;
    }

    // 失敗を「起きて当然」として扱う版。null でも例外を投げず false を返す。
    public static bool TryParseMinutes(string text, out int minutes)
    {
        minutes = 0;
        if (text is null) { return false; }

        var parts = text.Split(':');
        if (parts.Length != 2) { return false; }
        if (parts[0].Length != 2 || parts[1].Length != 2) { return false; }

        int h;
        int mm;
        if (!int.TryParse(parts[0], out h)) { return false; }
        if (!int.TryParse(parts[1], out mm)) { return false; }
        if (h < 0 || h > 23 || mm < 0 || mm > 59) { return false; }

        minutes = h * 60 + mm;
        return true;
    }
}

