using System;

class OrderException : Exception
{
    public OrderException(string message) : base(message) { }
}

class OutOfStockException : OrderException
{
    public int Requested { get; }
    public int Available { get; }

    public OutOfStockException(int requested, int available)
        : base("在庫不足: 要求 " + requested + " / 在庫 " + available)
    {
        Requested = requested;
        Available = available;
    }
}

class PaymentDeclinedException : OrderException
{
    public int Shortfall { get; }

    public PaymentDeclinedException(int shortfall)
        : base("残高不足: あと " + shortfall)
    {
        Shortfall = shortfall;
    }
}

class Solution
{
    // 在庫と残高を検査して合計金額を返す
    public static int Place(int stock, int qty, int balance, int price)
    {
        if (qty > stock)
        {
            throw new OutOfStockException(qty, stock);
        }
        int total = qty * price;
        if (total > balance)
        {
            throw new PaymentDeclinedException(total - balance);
        }
        return total;
    }

    // 注文処理に由来する失敗なら "order"、それ以外は "other"
    public static string Classify(Exception ex)
    {
        return ex is OrderException ? "order" : "other";
    }
}

