using System;

class Solution
{
    // text の start から length 文字を切り出す
    public static string Slice(string text, int start, int length)
    {
        if (text is null)
        {
            throw new ArgumentNullException(nameof(text));
        }
        if (start < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(start), "start は 0 以上である必要があります");
        }
        if (length < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(length), "length は 0 以上である必要があります");
        }
        if (start > text.Length - length)
        {
            throw new ArgumentException("範囲が文字列の外に出ています", nameof(length));
        }

        return text.Substring(start, length);
    }
}

