using System;
using System.Runtime.ExceptionServices;

class Solution
{
    // body を実行し、成否にかかわらず close を実行する。
    public static void RunAndClose(Action body, Action close)
    {
        Exception primary = null;

        try
        {
            body();
        }
        catch (Exception ex)
        {
            primary = ex;      // 元の例外をいったん保持する
        }

        try
        {
            close();
        }
        catch (Exception ex)
        {
            if (primary is null)
            {
                throw;         // 元の例外がないなら、後始末の例外をそのまま伝える
            }
            primary.Data["cleanup"] = ex.Message;   // 元の例外に添える
        }

        if (primary is not null)
        {
            ExceptionDispatchInfo.Capture(primary).Throw();
        }
    }
}

