using System;
using System.Collections.Generic;

class Tracked : IDisposable
{
    private readonly List<string> _log;
    private readonly string _name;

    public Tracked(List<string> log, string name)
    {
        _log = log;
        _name = name;
        _log.Add("open:" + name);
    }

    public void Dispose() { _log.Add("close:" + _name); }
}

class Solution
{
    // a, b, c を順に開き "work" を記録して返す
    public static List<string> Run()
    {
        var log = new List<string>();
        using var a = new Tracked(log, "a");
        using var b = new Tracked(log, "b");
        using var c = new Tracked(log, "c");
        log.Add("work");
        return log;
