answer_code:
using System;
using System.Collections.Generic;

class TreeNode
{
    public int Value;
    public TreeNode Left;
    public TreeNode Right;

    public TreeNode(int value) { Value = value; }
}

class Solution
{
    // 全ノードの値の合計
    public static long Sum(TreeNode root)
    {
        long total = 0;
        var stack = new Stack<TreeNode>();
        if (root is not null) { stack.Push(root); }
        while (stack.Count > 0)
        {
            var node = stack.Pop();
            total += node.Value;
            if (node.Left is not null) { stack.Push(node.Left); }
            if (node.Right is not null) { stack.Push(node.Right); }
        }
        return total;
    }

    // 最大の深さ (根だけなら 1、null なら 0)
    public static int MaxDepth(TreeNode root)
    {
        int best = 0;
        var stack = new Stack<(TreeNode Node, int Depth)>();
        if (root is not null) { stack.Push((root, 1)); }
        while (stack.Count > 0)
        {
            var item = stack.Pop();
            if (item.Depth > best) { best = item.Depth; }
            if (item.Node.Left is not null) { stack.Push((item.Node.Left, item.Depth + 1)); }
            if (item.Node.Right is not null) { stack.Push((item.Node.Right, item.Depth + 1)); }
        }
        return best;
    }
}

