using System;

class Solution
{
    // 窓の中の合計。部分配列をコピーして作らないこと。
    public static long SumSlice(ReadOnlySpan<int> window)
    {
        long total = 0;
        for (int i = 0; i < window.Length; i++)
        {
            total += window[i];
        }
        return total;
    }

    // 窓の中をその場で反転する。呼び出し元の配列にそのまま反映されること。
    public static void ReverseRange(Span<int> window)
    {
        for (int i = 0, j = window.Length - 1; i < j; i++, j--)
        {
            int tmp = window[i];
            window[i] = window[j];
            window[j] = tmp;
        }
    }
}

