using System;

class Solution
{
    public static int SumCsv(ReadOnlySpan<char> text)
    {
        int total = 0;
        ReadOnlySpan<char> rest = text;
        while (true)
        {
            int comma = rest.IndexOf(',');
            ReadOnlySpan<char> field = comma < 0 ? rest : rest[..comma];
            field = field.Trim();
            if (field.Length > 0) total += int.Parse(field);
            if (comma < 0) break;
            rest = rest[(comma + 1)..];
        }
        return total;
    }
}

