using System;

class Solution
{
    public static string ToBinary(int value)
    {
        Span<char> buf = stackalloc char[32];
        uint bits = unchecked((uint)value);
        for (int i = 31; i >= 0; i--)
        {
            buf[i] = (char)('0' + (int)(bits & 1u));
            bits >>= 1;
        }
        return new string(buf);
    }
}

