using System;

ref struct LineSplitter
{
    private ReadOnlySpan<char> _rest;
    private bool _done;

    public LineSplitter(ReadOnlySpan<char> text)
    {
        _rest = text;
        _done = text.Length == 0;
    }

    public bool TryNext(out ReadOnlySpan<char> line)
    {
        if (_done) { line = default; return false; }
        int i = _rest.IndexOf('\n');
        if (i < 0)
        {
            line = _rest;
            _rest = default;
            _done = true;
            return true;
        }
        line = _rest[..i];
        _rest = _rest[(i + 1)..];
        if (_rest.Length == 0) _done = true;
        return true;
    }
}

