struct Accumulator
{
    public int Total;
    public int Count;

    public Accumulator(int total, int count) { Total = total; Count = count; }

    // TODO: readonly struct にして、Add は自分を書き換えず新しい Accumulator を返すようにする
    public Accumulator Add(int x)
    {
        Total += x;
        Count++;
        return this;
    }
}

class Solution
{
    public static readonly Accumulator Origin = new Accumulator(0, 0);

    public static Accumulator SumAll(int[] xs)
    {
        var a = Origin;
        foreach (var x in xs) a = a.Add(x);
        return a;
    }
}

