using System;
using System.Buffers;

class Solution
{
    public static int[] SortedCopy(int[] src)
    {
        var pool = ArrayPool<int>.Shared;
        int[] buffer = pool.Rent(src.Length);
        try
        {
            Array.Copy(src, buffer, src.Length);
            Array.Sort(buffer, 0, src.Length);
            var result = new int[src.Length];
            Array.Copy(buffer, result, src.Length);
            return result;
        }
        finally
        {
            pool.Return(buffer);
        }
    }
}

