using System;
using System.Collections.Generic;

class Solution
{
    public static long CountWays(int n)
    {
        if (n < 0) return 0L;
        var memo = new Dictionary<int, long>();
        return Ways(n, memo);
    }

    private static long Ways(int n, Dictionary<int, long> memo)
    {
        if (n < 0) return 0L;
        if (n == 0) return 1L;
        long cached;
        if (memo.TryGetValue(n, out cached)) return cached;
        long result = Ways(n - 1, memo) + Ways(n - 2, memo) + Ways(n - 3, memo);
        memo[n] = result;
        return result;
    }
}

