using System;
using System.Collections.Generic;

class WeakCache<TValue> where TValue : class
{
    private readonly Dictionary<string, WeakReference<TValue>> _map =
        new Dictionary<string, WeakReference<TValue>>();

    public int Count { get { return _map.Count; } }

    public void Set(string key, TValue value)
    {
        _map[key] = new WeakReference<TValue>(value);
    }

    public bool TryGet(string key, out TValue value)
    {
        value = null;
        WeakReference<TValue> weak;
        if (!_map.TryGetValue(key, out weak)) return false;
        if (!weak.TryGetTarget(out value))
        {
            _map.Remove(key);
            value = null;
            return false;
        }
        return true;
    }
}

class Solution
{
    public static WeakCache<byte[]> NewCache() { return new WeakCache<byte[]>(); }
}

