using System;
using System.Collections.Generic;
using System.Text;

class Solution
{
    public static int CountRunes(string s)
    {
        int n = 0;
        foreach (var r in s.EnumerateRunes()) n++;
        return n;
    }

    public static string ReverseByRune(string s)
    {
        var runes = new List<Rune>();
        foreach (var r in s.EnumerateRunes()) runes.Add(r);
        var sb = new StringBuilder(s.Length);
        for (int i = runes.Count - 1; i >= 0; i--) sb.Append(runes[i].ToString());
        return sb.ToString();
    }
}

