using System;

class Solution
{
    public static DateTime NormalizeToUtc(DateTime dt)
    {
        switch (dt.Kind)
        {
            case DateTimeKind.Utc:
                return dt;
            case DateTimeKind.Local:
                return dt.ToUniversalTime();
            default:
                return DateTime.SpecifyKind(dt, DateTimeKind.Utc);
        }
    }
}

