using System;
using System.Threading;

class AtomicStats
{
    private int _count;
    private int _max = int.MinValue;

    public int Count { get { return System.Threading.Volatile.Read(ref _count); } }
    public int Max { get { return System.Threading.Volatile.Read(ref _max); } }

    public void Observe(int v)
    {
        System.Threading.Interlocked.Increment(ref _count);
        while (true)
        {
            int current = System.Threading.Volatile.Read(ref _max);
            if (v <= current)
            {
                return;
            }
            if (System.Threading.Interlocked.CompareExchange(ref _max, v, current) == current)
            {
                return;
            }
        }
    }
}

class Solution
{
    public static AtomicStats CreateStats()
    {
        return new AtomicStats();
    }
}

