using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

class Solution
{
    public static async Task<int[]> RunAllAsync(int taskCount, int limit)
    {
        var gate = new SemaphoreSlim(limit);
        int current = 0;
        int max = 0;
        int completed = 0;
        var tasks = new List<Task>();
        for (int i = 0; i < taskCount; i++)
        {
            tasks.Add(Task.Run(async () =>
            {
                await gate.WaitAsync().ConfigureAwait(false);
                try
                {
                    int now = Interlocked.Increment(ref current);
                    while (true)
                    {
                        int seen = Volatile.Read(ref max);
                        if (now <= seen || Interlocked.CompareExchange(ref max, now, seen) == seen)
                        {
                            break;
                        }
                    }
                    await Task.Delay(20).ConfigureAwait(false);
                    Interlocked.Increment(ref completed);
                }
                finally
                {
                    Interlocked.Decrement(ref current);
                    gate.Release();
                }
            }));
        }
        await Task.WhenAll(tasks).ConfigureAwait(false);
        return new int[] { Volatile.Read(ref max), Volatile.Read(ref completed) };
    }
}

