using System;
using System.Threading.Channels;
using System.Threading.Tasks;

class Solution
{
    public static async Task<int[]> PipelineAsync(int count)
    {
        var channel = Channel.CreateBounded<int>(2);

        var producer = Task.Run(async () =>
        {
            for (int i = 1; i <= count; i++)
            {
                await channel.Writer.WriteAsync(i).ConfigureAwait(false);
            }
            channel.Writer.Complete();
        });

        int sum = 0;
        int items = 0;
        await foreach (var v in channel.Reader.ReadAllAsync().ConfigureAwait(false))
        {
            sum += v;
            items++;
        }
        await producer.ConfigureAwait(false);
        return new int[] { sum, items };
    }
}

