using System;
using System.Threading;
using System.Threading.Tasks;

class Solution
{
    public static long SumSquares(int n)
    {
        long total = 0;
        Parallel.For(
            1,
            n + 1,
            () => 0L,
            (i, state, local) => local + (long)i * i,
            local => Interlocked.Add(ref total, local));
        return Interlocked.Read(ref total);
    }
}

