class LoopContext : System.Threading.SynchronizationContext
{
    private readonly System.Collections.Concurrent.BlockingCollection<System.Tuple<System.Threading.SendOrPostCallback, object>> _queue
        = new System.Collections.Concurrent.BlockingCollection<System.Tuple<System.Threading.SendOrPostCallback, object>>();

    public override void Post(System.Threading.SendOrPostCallback d, object state)
    {
        _queue.Add(System.Tuple.Create(d, state));
    }

    private void RunLoop()
    {
        System.Threading.SynchronizationContext.SetSynchronizationContext(this);
        foreach (var item in _queue.GetConsumingEnumerable())
        {
            item.Item1(item.Item2);
        }
    }

    public static System.Threading.Tasks.Task<int> RunOnLoop(System.Func<System.Threading.Tasks.Task<int>> start)
    {
        var ctx = new LoopContext();
        var thread = new System.Threading.Thread(ctx.RunLoop);
        thread.IsBackground = true;
        thread.Start();
        var tcs = new System.Threading.Tasks.TaskCompletionSource<System.Threading.Tasks.Task<int>>();
        ctx.Post(delegate
        {
            try { tcs.SetResult(start()); }
            catch (System.Exception e) { tcs.SetException(e); }
        }, null);
        return tcs.Task.Unwrap();
    }
}

