using System;
using System.Linq;
using System.Threading.Tasks;

class Solution
{
    // 完成済み: 負数なら例外を投げる
    private static async Task WorkAsync(int x)
    {
        await Task.Delay(5);
        if (x < 0)
        {
            throw new InvalidOperationException("bad:" + x);
        }
    }

    public static async Task<string[]> FailuresAsync(int[] inputs)
    {
        var tasks = inputs.Select(x => WorkAsync(x)).ToArray();
        var all = Task.WhenAll(tasks);
        try
        {
            await all.ConfigureAwait(false);
            return new string[0];
        }
        catch (Exception)
        {
            // 最初の 1 つしか飛んでこないので、ここでは握るだけにする
        }
        return all.Exception.InnerExceptions
            .Select(e => e.Message)
            .OrderBy(m => m, StringComparer.Ordinal)
            .ToArray();
    }
}

