using System;
using System.Threading;
using System.Threading.Tasks;

class Solution
{
    // 完成済み: 指定ミリ秒かかる本処理
    private static async Task<string> WorkAsync(int ms)
    {
        await Task.Delay(ms);
        return "done";
    }

    public static async Task<string> WithTimeoutAsync(int workMs, int timeoutMs)
    {
        using (var cts = new CancellationTokenSource())
        {
            var work = WorkAsync(workMs);
            var timeout = Task.Delay(timeoutMs, cts.Token);
            var winner = await Task.WhenAny(work, timeout).ConfigureAwait(false);
            if (winner == work)
            {
                cts.Cancel();
                return await work.ConfigureAwait(false);
            }
            return "timeout";
        }
    }
}

