using System;
using System.Collections.Generic;
using System.Threading.Tasks;

class Solution
{
    public static async IAsyncEnumerable<int> DoubledAsync(IEnumerable<int> src, List<string> log)
    {
        foreach (int x in src)
        {
            await Task.Yield();
            log.Add("visit " + x);
            yield return x * 2;
        }
    }

    public static async Task<int> SumAsync(IAsyncEnumerable<int> src)
    {
        int total = 0;
        await foreach (int value in src) total += value;
        return total;
    }
