using System;
using System.Threading;
using System.Threading.Tasks;

class Solution
{
    public static async Task<string> RunAsync(CancellationToken outer, int timeoutMs, int workMs)
    {
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(outer);
        linked.CancelAfter(timeoutMs);
        try
        {
            await Task.Delay(workMs, linked.Token);
            return "done";
        }
        catch (OperationCanceledException)
        {
            return outer.IsCancellationRequested ? "outer" : "timeout";
        }
    }
}

