using System;
using System.Linq.Expressions;

class Solution
{
    public class Employee
    {
        public string Name { get; set; } = "";
        public int Age { get; set; }
    }

    public static string Explain(Expression<Func<Employee, bool>> predicate)
    {
        if (predicate.Body is BinaryExpression binary
            && binary.Left is MemberExpression member
            && binary.Right is ConstantExpression constant)
        {
            string op = binary.NodeType switch
            {
                ExpressionType.Equal => "==",
                ExpressionType.GreaterThan => ">",
                ExpressionType.LessThan => "<",
                _ => ""
            };
            if (op.Length == 0) return "unsupported";
            return member.Member.Name + " " + op + " " + constant.Value;
        }
        return "unsupported";
    }
}

