using System;
using System.Runtime.InteropServices;

class Solution
{
    public static int SumPinned(int[] values)
    {
        GCHandle handle = GCHandle.Alloc(values, GCHandleType.Pinned);
        try
        {
            IntPtr head = handle.AddrOfPinnedObject();
            int total = 0;
            for (int i = 0; i < values.Length; i++)
            {
                total += Marshal.ReadInt32(head, i * sizeof(int));
            }
            return total;
        }
        finally
        {
            handle.Free();
        }
    }

    public static void SetPinned(int[] values, int index, int value)
    {
        GCHandle handle = GCHandle.Alloc(values, GCHandleType.Pinned);
        try
        {
            Marshal.WriteInt32(handle.AddrOfPinnedObject(), index * sizeof(int), value);
        }
        finally
        {
            handle.Free();
        }
    }
}

